Here is a comprehensive pytest suite covering happy paths, edge cases, and error cases.  
Assuming the function is imported as `from my_module import flatten_dict`.

```python
import pytest

# ---------------------------------------------------------------------------
# Happy Path
# ---------------------------------------------------------------------------

def test_flatten_empty_dict_returns_empty_dict():
    assert flatten_dict({}) == {}


def test_flatten_already_flat_dict_unchanged():
    d = {"a": 1, "b": 2, "c": 3}
    assert flatten_dict(d) == {"a": 1, "b": 2, "c": 3}


def test_flatten_single_level_nesting():
    d = {"a": {"b": 1}}
    assert flatten_dict(d) == {"a.b": 1}


def test_flatten_deep_nesting():
    d = {"a": {"b": {"c": {"d": 1}}}}
    assert flatten_dict(d) == {"a.b.c.d": 1}


def test_flatten_multiple_branches():
    d = {
        "a": {"b": 1, "c": 2},
        "d": 3,
        "e": {"f": {"g": 4}},
    }
    assert flatten_dict(d) == {
        "a.b": 1,
        "a.c": 2,
        "d": 3,
        "e.f.g": 4,
    }


@pytest.mark.parametrize(
    "sep, expected_key",
    [
        (".", "a.b"),
        ("/", "a/b"),
        ("_", "a_b"),
        ("::", "a::b"),
    ],
)
def test_flatten_custom_separator(sep, expected_key):
    d = {"a": {"b": 1}}
    assert flatten_dict(d, sep=sep) == {expected_key: 1}


def test_flatten_with_explicit_parent_key():
    """The parent_key parameter is public; calling it directly should prepend."""
    d = {"b": 1}
    assert flatten_dict(d, parent_key="a") == {"a.b": 1}


def test_flatten_parent_key_with_custom_separator():
    d = {"b": 1}
    assert flatten_dict(d, parent_key="a", sep="/") == {"a/b": 1}


# ---------------------------------------------------------------------------
# Edge Cases
# ---------------------------------------------------------------------------

def test_flatten_preserves_non_dict_values():
    """Lists, tuples, None, strings, ints, floats should remain as-is."""
    d = {
        "a": [1, 2, 3],
        "b": {"c": (4, 5)},
        "d": None,
        "e": "string",
        "f": {"g": {"h": 1.23}},
    }
    assert flatten_dict(d) == {
        "a": [1, 2, 3],
        "b.c": (4, 5),
        "d": None,
        "e": "string",
        "f.g.h": 1.23,
    }


def test_flatten_empty_nested_dict_is_omitted():
    """
    Because empty dicts produce no items, they disappear rather than
    appearing as an empty value. This documents current behavior.
    """
    d = {"a": {}}
    assert flatten_dict(d) == {}

    d2 = {"a": {"b": 1, "c": {}}}
    assert flatten_dict(d2) == {"a.b": 1}


def test_flatten_empty_string_keys():
    d = {"": {"a": 1}, "b": {"": 2}}
    assert flatten_dict(d) == {".a": 1, "b.": 2}


def test_flatten_keys_containing_separator_character():
    """
    The function blindly concatenates keys, so a key that itself contains
    the separator creates an ambiguous result. This test documents that.
    """
    d = {"a.b": {"c": 1}}
    assert flatten_dict(d, sep=".") == {"a.b.c": 1}


def test_flatten_numeric_keys():
    """Non-string keys are stringified by the f-string interpolation."""
    d = {1: {2: "value"}}
    assert flatten_dict(d) == {"1.2": "value"}


def test_flatten_does_not_mutate_input():
    d = {"a": {"b": 1}}
    original = {"a": {"b": 1}}
    flatten_dict(d)
    assert d == original


# ---------------------------------------------------------------------------
# Error Cases
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("bad_input", [None, "string", 123, [1, 2, 3], {1, 2, 3}])
def test_flatten_non_dict_input_raises_attribute_error(bad_input):
    with pytest.raises(AttributeError):
        flatten_dict(bad_input)


def test_flatten_none_separator_raises_type_error():
    """A None separator will blow up inside the f-string formatting."""
    with pytest.raises(TypeError):
        flatten_dict({"a": {"b": 1}}, sep=None)
```

### What the tests cover

| Category | Coverage |
|----------|----------|
| **Happy Path** | Empty dict, flat dict, shallow & deep nesting, multiple branches, custom separators, explicit `parent_key`. |
| **Edge Cases** | Non-dict values (lists, tuples, `None`), empty nested dicts (silently dropped), empty-string keys, keys that contain the separator, numeric keys, immutability of input. |
| **Error Cases** | Non-dict inputs (`None`, str, int, list, set) raise `AttributeError`, and a `None` separator raises `TypeError`. |

**Note on empty nested dicts:** If you want empty dicts to be preserved (e.g., `{"a": {}}` → `{"a": {}}`), the implementation would need a special-case check; the test above documents the *current* behavior so you can detect if it ever changes.
